        if abs(di)!=abs(dj): continue
        step=(di//abs(di),dj//abs(dj)); n=min(abs(i2-i1),abs(j2-j1))
        for k in range(1,n):
            o=(i1+k*step[0],j1+k*step[1])
            if 0<=o[0]<h and 0<=o[1]<w and out[o[0]][o[1]]==bg: out[o[0]][o[1]]=col
    for col,ps in list(pts.items()):
        if len(ps)>1 or False: continue
